example_solution:
import gleam/int
import gleam/list

pub fn factors(value: Int) -> List(Int) {
  find_factors(value, 2, [], [])
}

fn find_factors(
  value: Int,
  guess: Int,
  primes: List(Int),
  factors: List(Int),
) -> List(Int) {
  case guess * guess > value {
    True if value == 1 -> list.sort(factors, int.compare)
    True -> list.sort([value, ..factors], int.compare)
    False -> {
      let next_guess = case guess % 6 {
        1 -> guess + 4
        2 -> 3
        3 -> 5
        _ -> guess + 2
      }

      case list.all(primes, fn(prime) { guess % prime != 0 }) {
        False -> find_factors(value, next_guess, primes, factors)
        True -> {
          let #(value, factors) = reduce(value, guess, factors)
          let primes = [guess, ..primes]
          find_factors(value, next_guess, primes, factors)
        }
      }
    }
  }
}

fn reduce(value: Int, prime: Int, factors: List(Int)) -> #(Int, List(Int)) {
  case value % prime {
    0 -> reduce(value / prime, prime, [prime, ..factors])
    _ -> #(value, factors)
  }
}

test_code:
import exercism/should
import exercism/test_runner
import prime_factors

pub fn main() {
  test_runner.main()
}

pub fn no_factors_test() {
  prime_factors.factors(1)
  |> should.equal([])
}

pub fn prime_number_test() {
  prime_factors.factors(2)
  |> should.equal([2])
}

pub fn another_prime_number_test() {
  prime_factors.factors(3)
  |> should.equal([3])
}

pub fn square_of_a_prime_test() {
  prime_factors.factors(9)
  |> should.equal([3, 3])
}

pub fn product_of_first_prime_test() {
  prime_factors.factors(4)
  |> should.equal([2, 2])
}

pub fn cube_of_a_prime_test() {
  prime_factors.factors(8)
  |> should.equal([2, 2, 2])
}

pub fn product_of_second_prime_test() {
  prime_factors.factors(27)
  |> should.equal([3, 3, 3])
}

pub fn product_of_third_prime_test() {
  prime_factors.factors(625)
  |> should.equal([5, 5, 5, 5])
}

pub fn product_of_first_and_second_prime_test() {
  prime_factors.factors(6)
  |> should.equal([2, 3])
}

pub fn product_of_primes_and_non_primes_test() {
  prime_factors.factors(12)
  |> should.equal([2, 2, 3])
}

pub fn product_of_primes_test() {
  prime_factors.factors(901_255)
  |> should.equal([5, 17, 23, 461])
}

pub fn factors_include_a_large_prime_test() {
  prime_factors.factors(93_819_012_551)
  |> should.equal([11, 9539, 894_119])
}
